def extract(tree):
    rows = tree.where(content_desc="sourceLanguagePicker")
    if not rows:
        raise ValueError("Source language picker is absent")
    return any("English" in ((r.get("name") or "") + " " + (r.get("text") or "") + " " + (r.get("content_desc") or "")) for r in rows)

def extract(tree):
    rows = tree.where(content_desc="targetLanguagePicker")
    if not rows:
        raise ValueError("Destination language picker is absent")
    return any("Spanish" in ((r.get("name") or "") + " " + (r.get("text") or "") + " " + (r.get("content_desc") or "")) for r in rows)
